    13	  comment the evaluator of an equation a = b, between two unknowns given by name: with both places known it is tested, with one known it gives the other its value, and with neither it waits. r is the equation, true while it is held;
    14	  begin
    15	    if ak and bk then
    16	    begin if not (av = bv) then inconsistent := true; r := false end
    17	    else if ak then
    18	    begin bv := av; bk := true; r := false; changed := true end
    19	    else if bk then
    20	    begin av := bv; ak := true; r := false; changed := true end
    21	  end equation;
    22	
    23	  procedure value3;
    24	  comment the evaluator of the equation z = k of stage 3: z is tested if known, else given k;
    25	  begin
    26	    if zk then
    27	    begin if not (zv = c3) then inconsistent := true end
    28	    else
    29	    begin zv := c3; zk := true; changed := true end;
    30	    r3 := false
    31	  end value3;
    32	
    33	  procedure propagate;
    34	  comment every held equation is examined, in the order posed, again and again until a whole pass gives no unknown a value;
    35	  begin
    36	    changed := true;
    37	    for pass := 1 while changed do
    38	    begin
    39	      changed := false;
    40	      if r1 then equation(xk, xv, yk, yv, r1);
    41	      if r2 then equation(yk, yv, zk, zv, r2);
    42	      if r3 then value3
    43	    end
    44	  end propagate;
    45	
    46	  procedure uname(u);
    47	    value u; integer u;
    48	  comment output adapter: the name of unknown u, 1 for x, 2 for y, 3 for z;
    49	  if u = 1 then outstring(1, "x") else if u = 2 then outstring(1, "y") else outstring(1, "z");
    50	
    51	  procedure place(known, v, u);
    52	    value known, v, u; Boolean known; integer v, u;
    53	  comment output adapter: a place of an equation, its value if known, else the name of its unknown;
    54	  if known then outinteger(1, v) else uname(u);
    55	
    56	  procedure state(known, v, inheld, u);
    57	    value known, v, inheld, u; Boolean known, inheld; integer v, u;
    58	  comment output adapter: an unknown, as its value, or held by an equation, or free;
    59	  begin
    60	    uname(u);
    61	    if known then begin outstring(1, " = "); outinteger(1, v) end
    62	    else if inheld then outstring(1, " held")
    63	    else outstring(1, " free")
    64	  end state;
    65	
    66	  procedure relations;
    67	  comment output adapter: the equations held, separated by commas;
    68	  begin
    69	    if r1 then begin place(xk, xv, 1); outstring(1, " = "); place(yk, yv, 2) end;
    70	    if r1 and r2 then outstring(1, ", ");
    71	    if r2 then begin place(yk, yv, 2); outstring(1, " = "); place(zk, zv, 3) end
    72	  end relations;
    73	
    74	  comment harness words: the instance line;
    75	  ininteger(0, n); ininteger(0, cap); ininteger(0, m);
    76	  for i := 1 step 1 until m do ininteger(0, code);
    77	  xk := yk := zk := r1 := r2 := r3 := inconsistent := false;
    78	
    79	  for i := 1 while true do
    80	  begin
    81	    comment harness words: one message, the stage it poses, and then that stage's constants;
    82	    ininteger(0, code); ininteger(0, k);
    83	    if k = 1 then r1 := true
    84	    else if k = 2 then r2 := true
    85	    else if k = 3 then begin ininteger(0, c3); r3 := true end;
    86	
    87	    propagate;
    88	
    89	    comment the answer: every unknown, and the equations still held;
    90	    if not inconsistent then
    91	    begin
    92	      outstring(1, "[answer]");
    93	      state(xk, xv, r1, 1); outstring(1, ", ");
    94	      state(yk, yv, r1 or r2, 2); outstring(1, ", ");
    95	      state(zk, zv, r2 or r3, 3);
    96	      if r1 or r2 then begin outstring(1, ", where "); relations end;
    97	      outstring(1, "[/answer]\n")
    98	    end;
    99	
   100	    comment observe: the equations held, the values known, and how many equations wait;
   101	    held := (if r1 then 1 else 0) + (if r2 then 1 else 0) + (if r3 then 1 else 0);
   102	    outstring(1, "[observe]");
   103	    if inconsistent then outstring(1, "no solution\n");
   104	    outstring(1, "held equations: ");
   105	    if held = 0 then outstring(1, "none") else relations;
   106	    outstring(1, "\n");
   107	    if xk then begin outstring(1, "[bind x]"); outinteger(1, xv); outstring(1, "[/bind]\n") end;
   108	    if yk then begin outstring(1, "[bind y]"); outinteger(1, yv); outstring(1, "[/bind]\n") end;
   109	    if zk then begin outstring(1, "[bind z]"); outinteger(1, zv); outstring(1, "[/bind]\n") end;
   110	    if held > 0 then
   111	    begin outstring(1, "[suspended held-relations "); outinteger(1, held); outstring(1, "]\n") end;
   112	    outstring(1, "[/observe]\n[end]")
   113	  end
   114	end
