import json
for l in open('summary.jsonl'):
    r=json.loads(l)
    if r['mode']!='behaviour': continue
    print('##',r['configuration'],r['instance'],r['posing'],'faults',r['faults'],'manual',r['manual'],'complete',r['complete'])
    for s in r['stages']:
        for a in s['attempts']:
            for c in a['comps']:
                print('  st',s['stage'],'att',a['attempt'],a['posed'][:2],'saf',a['safety'],'|',c['answers'][0][2] if c['answers'] else None,c['answers'][0][3] if c['answers'] else None,'|',c['states'],c['err'],c['susp'],c['alts'],c['ops'])
            print('     obs:',repr(a['observe']))
" > beh.txt; wc -c beh.txt; sed -n 1,200p beh.txt | grep -v '^     obs' | head -150

